const providerOAuthCrypto = require('crypto');
const PROVIDER_OAUTH_REQUIRED_SCOPE = 'salesforce.integration';
const PROVIDER_OAUTH_TOKEN_TTL_SECONDS = 900;

function providerOAuthEnv(name) {
  try { return String($env[name] || ''); } catch (error) { return ''; }
}

function providerOAuthHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}

function providerOAuthScopes(value) {
  return [...new Set(String(value || '').trim().split(/\s+/).filter(Boolean))];
}

function providerOAuthBase64Url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function providerOAuthDecodeSegment(segment) {
  if (!/^[A-Za-z0-9_-]+$/.test(String(segment || ''))) throw new Error('invalid base64url');
  const padding = (4 - (segment.length % 4)) % 4;
  const decoded = Buffer.from(segment + '='.repeat(padding), 'base64');
  if (providerOAuthBase64Url(decoded) !== segment) throw new Error('non-canonical base64url');
  return decoded;
}

function providerOAuthFailure(statusCode, error, description) {
  return { ok: false, statusCode, body: { error, error_description: description } };
}

function providerOAuthInvalidToken() {
  return providerOAuthFailure(401, 'invalid_token', 'The access token is invalid or expired.');
}

function validateProviderBearerJwt(request) {
  const jwtSecret = providerOAuthEnv('RENOV_OAUTH_JWT_SECRET');
  const issuer = providerOAuthEnv('RENOV_OAUTH_ISSUER');
  const audience = providerOAuthEnv('RENOV_OAUTH_AUDIENCE');
  const configuredClientId = providerOAuthEnv('RENOV_OAUTH_CLIENT_ID');
  const configuredScopes = providerOAuthScopes(providerOAuthEnv('RENOV_OAUTH_SCOPE'));
  const allowedClientIds = providerOAuthEnv('RENOV_PROVIDER_CLIENT_IDS')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  if (!jwtSecret || !issuer || !audience || !configuredClientId
      || !configuredScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || allowedClientIds.length === 0) {
    return providerOAuthFailure(503, 'server_error', 'OAuth server configuration is unavailable.');
  }

  const headers = request && request.headers && typeof request.headers === 'object' ? request.headers : {};
  const authorization = String(providerOAuthHeader(headers, 'authorization') || '');
  const bearerMatch = authorization.match(/^Bearer[ \t]+([^ \t]+)[ \t]*$/i);
  const xClientId = String(providerOAuthHeader(headers, 'x-client-id') || '').trim().toLowerCase();
  if (!bearerMatch || !xClientId || !allowedClientIds.includes(xClientId)) return providerOAuthInvalidToken();

  const token = bearerMatch[1];
  const parts = token.split('.');
  if (parts.length !== 3) return providerOAuthInvalidToken();

  let header;
  let payload;
  let signature;
  try {
    header = JSON.parse(providerOAuthDecodeSegment(parts[0]).toString('utf8'));
    payload = JSON.parse(providerOAuthDecodeSegment(parts[1]).toString('utf8'));
    signature = providerOAuthDecodeSegment(parts[2]);
  } catch (error) {
    return providerOAuthInvalidToken();
  }
  if (!header || typeof header !== 'object' || Array.isArray(header) || header.alg !== 'HS256') {
    return providerOAuthInvalidToken();
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return providerOAuthInvalidToken();

  const expectedSignature = providerOAuthCrypto
    .createHmac('sha256', jwtSecret)
    .update(parts[0] + '.' + parts[1], 'utf8')
    .digest();
  if (signature.length !== expectedSignature.length
      || !providerOAuthCrypto.timingSafeEqual(signature, expectedSignature)) {
    return providerOAuthInvalidToken();
  }

  if (payload.iss !== issuer || payload.aud !== audience
      || typeof payload.sub !== 'string' || typeof payload.client_id !== 'string'
      || payload.sub !== configuredClientId || payload.client_id !== configuredClientId
      || payload.sub !== payload.client_id) {
    return providerOAuthInvalidToken();
  }

  const tokenScopes = providerOAuthScopes(payload.scope);
  if (!tokenScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || !tokenScopes.every((scope) => configuredScopes.includes(scope))) {
    return providerOAuthFailure(403, 'insufficient_scope', 'The access token lacks the required scope.');
  }

  const numericDatesAreValid = Number.isSafeInteger(payload.iat)
    && Number.isSafeInteger(payload.nbf)
    && Number.isSafeInteger(payload.exp);
  const now = Math.floor(Date.now() / 1000);
  if (!numericDatesAreValid
      || payload.nbf !== payload.iat
      || payload.exp - payload.iat !== PROVIDER_OAUTH_TOKEN_TTL_SECONDS
      || payload.iat > now
      || payload.nbf > now
      || payload.exp <= now) {
    return providerOAuthInvalidToken();
  }

  return {
    ok: true,
    clientId: payload.client_id,
    providerClientId: xClientId,
    scope: tokenScopes.join(' '),
    claims: payload,
  };
}

const providerOAuthRequest = $input.first().json || {};
const providerOAuthAuth = validateProviderBearerJwt(providerOAuthRequest);
if (!providerOAuthAuth.ok) {
  return [{ json: { statusCode: providerOAuthAuth.statusCode, body: providerOAuthAuth.body, authorized: false } }];
}

function env(name, fallback = '') {
  try { return $env[name] || fallback; } catch (e) { return fallback; }
}

const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};
const params = request.params ?? {};

// =====================================================================
// REUSABLE SNIPPET — kept identical to AUTH-01 / Validate Provider API Key.
// Contract: docs/CONTRATO_API_SALESFORCE.md, "Autenticacion (T-1.17)".
// =====================================================================
function response(statusCode, responseBody) {
  return [{ json: { statusCode, body: responseBody } }];
}

function apiError(statusCode, code, message, details = []) {
  return response(statusCode, { code, message, details });
}

function readHeader(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) {
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return '';
}

// ======================= end of reusable snippet =======================

// SQL comes from renovaciones-db/sync/*.sql, embedded verbatim at build time.
// It is chosen by a validated enum and never built from request data: every
// value travels as a query parameter.
const SQL = {
  "accounts": "-- POST /v1/assignments/accounts  (work item 16155)\n-- $1 = JSON array of normalised records, $2 = syncBatchId.\nWITH incoming AS (\n  SELECT * FROM jsonb_to_recordset($1::jsonb) AS x(\n    sf_account_id text,\n    phone         text,\n    sf_owner_id   text,\n    sf_username   text,\n    full_name     text,\n    status        text\n  )\n),\n-- ON CONFLICT DO UPDATE returns the row whether it was inserted or already\n-- existed, so this CTE yields every advisor named in the batch. That is what\n-- lets the account upsert resolve advisor_id in the same statement.\ntouched_advisors AS (\n  INSERT INTO renovation_dev.advisors (salesforce_user_id, full_name, active, synced_at)\n  SELECT DISTINCT\n         i.sf_owner_id,\n         coalesce(nullif(btrim(i.sf_username), ''), i.sf_owner_id),\n         true,\n         now()\n    FROM incoming i\n   WHERE nullif(btrim(coalesce(i.sf_owner_id, '')), '') IS NOT NULL\n  ON CONFLICT (salesforce_user_id) DO UPDATE\n    SET synced_at = now()\n  RETURNING id, salesforce_user_id\n),\nupserted AS (\n  INSERT INTO renovation_dev.quicklink_account_assignments AS account (\n    salesforce_contact_id, full_name, phone, sf_owner_id, sf_username,\n    advisor_id, sync_batch_id, deleted_at, synced_at\n  )\n  SELECT i.sf_account_id,\n         nullif(btrim(coalesce(i.full_name, '')), ''),\n         i.phone,\n         nullif(btrim(coalesce(i.sf_owner_id, '')), ''),\n         nullif(btrim(coalesce(i.sf_username, '')), ''),\n         adv.id,\n         $2,\n         NULL,\n         now()\n    FROM incoming i\n    LEFT JOIN touched_advisors adv ON adv.salesforce_user_id = i.sf_owner_id\n  ON CONFLICT (salesforce_contact_id) DO UPDATE SET\n    full_name     = coalesce(EXCLUDED.full_name, account.full_name),\n    phone         = EXCLUDED.phone,\n    sf_owner_id   = EXCLUDED.sf_owner_id,\n    sf_username   = EXCLUDED.sf_username,\n    advisor_id    = EXCLUDED.advisor_id,\n    sync_batch_id = EXCLUDED.sync_batch_id,\n    -- A record reported again is alive again: undo any anti-zombie purge.\n    deleted_at    = NULL,\n    synced_at     = now(),\n    updated_at    = now()\n  RETURNING id\n)\nSELECT (SELECT count(*) FROM upserted)::int AS upserted,\n       '[]'::jsonb AS db_rejected;\n",
  "vehicles": "-- POST /v1/assignments/vehicles  (work item 16171)\n-- $1 = JSON array of normalised records, $2 = syncBatchId.\nWITH incoming AS (\n  SELECT * FROM jsonb_to_recordset($1::jsonb) AS x(\n    sf_vehicle_id  text,\n    sf_account_id  text,\n    brand          text,\n    model          text,\n    sf_placa       text,\n    sf_chasis      text,\n    vehicle_type   text,\n    service_name   text\n  )\n),\nresolved AS (\n  SELECT i.*, a.id AS account_uuid\n    FROM incoming i\n    LEFT JOIN renovation_dev.quicklink_account_assignments a\n           ON a.salesforce_contact_id = i.sf_account_id\n          AND a.deleted_at IS NULL\n),\n-- A vehicle whose account was never synced cannot be stored; it is reported\n-- back rather than silently dropped by the join.\nunmatched AS (\n  SELECT sf_vehicle_id FROM resolved WHERE account_uuid IS NULL\n),\nupserted AS (\n  INSERT INTO renovation_dev.quicklink_vehicle_assignments (\n    customer_id, salesforce_vehicle_id, brand, model, sf_placa, sf_chasis,\n    vehicle_type, service_name, sync_batch_id, deleted_at, synced_at\n  )\n  SELECT r.account_uuid,\n         r.sf_vehicle_id,\n         r.brand,\n         nullif(btrim(coalesce(r.model, '')), ''),\n         nullif(btrim(coalesce(r.sf_placa, '')), ''),\n         nullif(btrim(coalesce(r.sf_chasis, '')), ''),\n         coalesce(nullif(btrim(coalesce(r.vehicle_type, '')), ''), 'car')::renovation_dev.vehicle_type,\n         r.service_name,\n         $2,\n         NULL,\n         now()\n    FROM resolved r\n   WHERE r.account_uuid IS NOT NULL\n  ON CONFLICT (salesforce_vehicle_id) DO UPDATE SET\n    customer_id   = EXCLUDED.customer_id,\n    brand         = EXCLUDED.brand,\n    model         = EXCLUDED.model,\n    sf_placa      = EXCLUDED.sf_placa,\n    sf_chasis     = EXCLUDED.sf_chasis,\n    vehicle_type  = EXCLUDED.vehicle_type,\n    service_name  = EXCLUDED.service_name,\n    sync_batch_id = EXCLUDED.sync_batch_id,\n    deleted_at    = NULL,\n    synced_at     = now(),\n    updated_at    = now()\n  RETURNING id\n)\nSELECT (SELECT count(*) FROM upserted)::int AS upserted,\n       coalesce(\n         (SELECT jsonb_agg(jsonb_build_object('sf_vehicleId', sf_vehicle_id,\n                                              'reason', 'UNKNOWN_ACCOUNT'))\n            FROM unmatched),\n         '[]'::jsonb\n       ) AS db_rejected;\n",
  "contracts": "-- POST /v1/assignments/contracts (work item 16187)\n-- $1 = JSON array of normalised records, $2 = syncBatchId.\nWITH incoming AS (\n  SELECT * FROM jsonb_to_recordset($1::jsonb) AS x(\n    sf_contract_id text,\n    sf_account_id  text,\n    sf_vehicle_id  text,\n    sf_owner_id    text,\n    sf_start_date  date,\n    sf_end_date    date,\n    contract_status text\n  )\n),\nresolved AS (\n  SELECT i.*, a.id AS account_uuid, v.id AS vehicle_uuid\n    FROM incoming i\n    LEFT JOIN renovation_dev.quicklink_account_assignments a\n           ON a.salesforce_contact_id = i.sf_account_id\n          AND a.deleted_at IS NULL\n     LEFT JOIN renovation_dev.quicklink_vehicle_assignments v\n            ON v.salesforce_vehicle_id = i.sf_vehicle_id\n           AND v.customer_id = a.id\n           AND v.deleted_at IS NULL\n),\nunmatched AS (\n  SELECT sf_contract_id, sf_account_id, sf_vehicle_id\n    FROM resolved\n   WHERE account_uuid IS NULL OR vehicle_uuid IS NULL\n),\nupserted AS (\n  INSERT INTO renovation_dev.quicklink_contract_assignments (\n    sf_contract_id, account_id, vehicle_id, sf_account_id, sf_vehicle_id,\n    sf_owner_id, sf_start_date, sf_end_date, contract_status,\n    sync_batch_id, deleted_at, synced_at\n  )\n  SELECT r.sf_contract_id, r.account_uuid, r.vehicle_uuid, r.sf_account_id,\n         r.sf_vehicle_id, r.sf_owner_id, r.sf_start_date, r.sf_end_date,\n         nullif(btrim(coalesce(r.contract_status, '')), ''),\n         $2, NULL, now()\n    FROM resolved r\n   WHERE r.account_uuid IS NOT NULL\n     AND r.vehicle_uuid IS NOT NULL\n  ON CONFLICT (sf_contract_id) DO UPDATE SET\n    account_id      = EXCLUDED.account_id,\n    vehicle_id      = EXCLUDED.vehicle_id,\n    sf_account_id   = EXCLUDED.sf_account_id,\n    sf_vehicle_id   = EXCLUDED.sf_vehicle_id,\n    sf_owner_id     = EXCLUDED.sf_owner_id,\n    sf_start_date   = EXCLUDED.sf_start_date,\n    sf_end_date     = EXCLUDED.sf_end_date,\n    contract_status = EXCLUDED.contract_status,\n    sync_batch_id   = EXCLUDED.sync_batch_id,\n    deleted_at      = NULL,\n    synced_at       = now(),\n    updated_at      = now()\n  RETURNING id, vehicle_id, sf_end_date\n),\n-- Keep the denormalised copy the campaign view falls back to in step.\nmirrored AS (\n  UPDATE renovation_dev.quicklink_vehicle_assignments v\n     SET expiration_date = u.sf_end_date\n    FROM upserted u\n   WHERE v.id = u.vehicle_id\n     AND u.sf_end_date IS NOT NULL\n  RETURNING v.id\n)\nSELECT (SELECT count(*) FROM upserted)::int AS upserted,\n        coalesce(\n          (SELECT jsonb_agg(jsonb_build_object('sf_contractId', sf_contract_id,\n                                               'sf_accountId', sf_account_id,\n                                               'sf_vehicleId', sf_vehicle_id,\n                                               'reason', 'UNKNOWN_ACCOUNT'))\n            FROM unmatched),\n         '[]'::jsonb\n       ) AS db_rejected;\n",
  "reassign": "-- PATCH /v1/assignments/{accountId} (work item 16155)\n-- Takes one parameter: a JSON array holding the single record to reassign.\n-- No sync batch id: a reassignment is a point change and must not be swept up\n-- by the anti-zombie purge of the next full sync.\nWITH incoming AS (\n  SELECT * FROM jsonb_to_recordset($1::jsonb) AS x(\n    sf_account_id text,\n    sf_owner_id   text,\n    sf_username   text\n  )\n),\ntouched_advisors AS (\n  INSERT INTO renovation_dev.advisors (salesforce_user_id, full_name, active, synced_at)\n  SELECT DISTINCT\n         i.sf_owner_id,\n         coalesce(nullif(btrim(i.sf_username), ''), i.sf_owner_id),\n         true,\n         now()\n    FROM incoming i\n  ON CONFLICT (salesforce_user_id) DO UPDATE\n    SET synced_at = now()\n  RETURNING id, salesforce_user_id\n),\nreassigned AS (\n  UPDATE renovation_dev.quicklink_account_assignments a\n     SET sf_owner_id = i.sf_owner_id,\n         sf_username = nullif(btrim(coalesce(i.sf_username, '')), ''),\n         advisor_id  = adv.id,\n         synced_at   = now(),\n         updated_at  = now()\n    FROM incoming i\n    JOIN touched_advisors adv ON adv.salesforce_user_id = i.sf_owner_id\n   WHERE a.salesforce_contact_id = i.sf_account_id\n     AND a.deleted_at IS NULL\n  RETURNING a.id\n)\nSELECT (SELECT count(*) FROM reassigned)::int AS upserted,\n       '[]'::jsonb AS db_rejected;\n"
};

const BATCH_LIMIT = 2000;

// Commercial service name by brand (docs/REGLAS_NEGOCIO.md section 2). The
// provider calculates it: Salesforce does not send it, so a rename here never
// requires a release on their side.
const SERVICE_BY_BRAND = {
  kia: 'telemetría KIA',
  hyundai: 'My Hyundai Link',
  ford: 'Quito Motors Connect',
  jac: 'Jac Connect',
  ankai: 'Camioneta del Ecuador',
  honda: 'Honda Connect',
  'land rover': 'Land Rover Connect',
  bajaj: 'Quicklink Motos',
};

function serviceNameFor(brand, vehicleType) {
  const key = String(brand || '').trim().toLowerCase();
  if (key === 'honda' && vehicleType === 'motorcycle') return 'Honda Satelital';
  if (SERVICE_BY_BRAND[key]) return SERVICE_BY_BRAND[key];
  return vehicleType === 'motorcycle' ? 'Quicklink Motos' : 'Quicklink Autos';
}

// E.164 with an Ecuadorian default, per T-1.16.
function normalisePhone(raw) {
  let value = String(raw ?? '').trim();
  if (!value) return null;
  const hadPlus = value.startsWith('+');
  value = value.replace(/[^0-9]/g, '');
  if (!value) return null;
  if (!hadPlus) {
    if (value.startsWith('00')) value = value.slice(2);
    else if (value.startsWith('593')) { /* already the country code */ }
    else if (value.startsWith('0')) value = '593' + value.slice(1);
    else if (value.length === 9) value = '593' + value;
  }
  const candidate = '+' + value;
  return /^\+[1-9][0-9]{7,14}$/.test(candidate) ? candidate : null;
}

function text(value) {
  const trimmed = String(value ?? '').trim();
  return trimmed === '' ? null : trimmed;
}

function isIsoDate(value) {
  return value === null || /^\d{4}-\d{2}-\d{2}$/.test(String(value));
}

const ENTITIES = {
  accounts: {
    key: 'sf_accountId',
    sql: SQL.accounts,
    map(record, reject) {
      const sfAccountId = text(record.sf_accountId);
      const phone = normalisePhone(record.sf_phone ?? record.phone);
      if (!sfAccountId) return reject('MISSING_REQUIRED_FIELD', null);
      if (!phone) return reject('INVALID_PHONE', sfAccountId);
      return {
        sf_account_id: sfAccountId,
        phone: phone,
        sf_owner_id: text(record.sf_ownerId),
        sf_username: text(record.sf_username),
        full_name: text(record.sf_accountName ?? record.full_name),
        status: text(record.status),
      };
    },
  },
  vehicles: {
    key: 'sf_vehicleId',
    sql: SQL.vehicles,
    map(record, reject) {
      const sfVehicleId = text(record.sf_vehicleId);
      const sfAccountId = text(record.sf_accountId);
      const brand = text(record.sf_marca ?? record.brand);
      if (!sfVehicleId || !sfAccountId || !brand) {
        return reject('MISSING_REQUIRED_FIELD', sfVehicleId);
      }
      const vehicleType = String(record.vehicle_type ?? 'car').toLowerCase() === 'motorcycle'
        ? 'motorcycle'
        : 'car';
      return {
        sf_vehicle_id: sfVehicleId,
        sf_account_id: sfAccountId,
        brand: brand,
        model: text(record.sf_modelo ?? record.model),
        sf_placa: text(record.sf_placa),
        sf_chasis: text(record.sf_chasis),
        vehicle_type: vehicleType,
        service_name: serviceNameFor(brand, vehicleType),
      };
    },
  },
  contracts: {
    key: 'sf_contractId',
    sql: SQL.contracts,
    map(record, reject) {
      const sfContractId = text(record.sf_contractId);
      const sfAccountId = text(record.sf_accountId);
      if (!sfContractId || !sfAccountId) {
        return reject('MISSING_REQUIRED_FIELD', sfContractId);
      }
      const startDate = text(record.sf_startDate);
      const endDate = text(record.sf_endDate);
      if (!isIsoDate(startDate) || !isIsoDate(endDate)) {
        return reject('INVALID_PAYLOAD', sfContractId);
      }
      return {
        sf_contract_id: sfContractId,
        sf_account_id: sfAccountId,
        sf_vehicle_id: text(record.sf_vehicleId),
        sf_owner_id: text(record.sf_ownerId),
        sf_start_date: startDate,
        sf_end_date: endDate,
        contract_status: text(record.contractStatus ?? record.contract_status),
      };
    },
  },
};

// This n8n instance registers webhook paths literally, so ':entity' never
// resolves as a route parameter. The entity is taken from the last path
// segment instead; params is still honoured in case that changes.
function entityFromPath() {
  const url = String(request.webhookUrl ?? request.path ?? '');
  const segments = url.split('?')[0].split('/').filter(Boolean);
  return segments.length ? segments[segments.length - 1].toLowerCase() : '';
}

const isReassign = request.method === 'PATCH';

// --- PATCH /v1/assignments/{accountId} ---------------------------------
if (isReassign) {
  const accountId = text(params.accountId ?? body.sf_accountId);
  const ownerId = text(body.sf_ownerId);
  if (!accountId || !ownerId) {
    return apiError(400, 'INVALID_PAYLOAD', 'Se requieren el accountId en la ruta y sf_ownerId en el body.');
  }
  return [{
    json: {
      statusCode: 200,
      ok: true,
      entity: 'reassign',
      sql: SQL.reassign,
      query_params: [JSON.stringify([{
        sf_account_id: accountId,
        sf_owner_id: ownerId,
        sf_username: text(body.sf_username),
      }])],
      sync_batch_id: null,
      received: 1,
      rejected: 0,
      rejected_records: [],
    },
  }];
}

// --- POST /v1/assignments/{entity} -------------------------------------
const entityName = String(params.entity ?? '').toLowerCase() || entityFromPath();
const entity = ENTITIES[entityName];

if (!entity) {
  return apiError(
    400,
    'INVALID_PAYLOAD',
    'Entidad no soportada: ' + entityName + '. Use accounts, vehicles o contracts.',
  );
}

const syncBatchId = text(body.syncBatchId);
if (!syncBatchId) {
  return apiError(400, 'INVALID_PAYLOAD', 'Falta syncBatchId.');
}

const records = body.records;
if (!Array.isArray(records) || records.length === 0) {
  return apiError(400, 'INVALID_PAYLOAD', 'records debe ser un arreglo con al menos un registro.');
}
if (records.length > BATCH_LIMIT) {
  return apiError(
    413,
    'INVALID_PAYLOAD',
    'El lote supera el maximo de ' + BATCH_LIMIT + ' registros por request.',
  );
}

const rows = [];
const rejected = [];
const seen = new Set();

for (const record of records) {
  let rejectedHere = null;
  const reject = (reason, key) => {
    rejectedHere = { [entity.key]: key, reason: reason };
    return null;
  };

  const mapped = entity.map(record ?? {}, reject);

  if (rejectedHere) {
    rejected.push(rejectedHere);
    continue;
  }

  // T-1.16: two records with the same primary key cannot coexist in one batch.
  const primaryKey = mapped[Object.keys(mapped)[0]];
  if (seen.has(primaryKey)) {
    rejected.push({ [entity.key]: primaryKey, reason: 'DUPLICATE_KEY_IN_BATCH' });
    continue;
  }
  seen.add(primaryKey);
  rows.push(mapped);
}

if (rows.length === 0) {
  return response(422, {
    code: 'INVALID_PAYLOAD',
    message: 'Ningun registro del lote es valido.',
    syncBatchId: syncBatchId,
    received: records.length,
    upserted: 0,
    rejected: rejected.length,
    rejectedRecords: rejected,
  });
}

return [{
  json: {
    statusCode: 200,
    ok: true,
    entity: entityName,
    sql: entity.sql,
    query_params: [JSON.stringify(rows), syncBatchId],
    sync_batch_id: syncBatchId,
    received: records.length,
    rejected: rejected.length,
    rejected_records: rejected,
  },
}];

// Merges what the validator rejected up front with what the database refused,
// and shapes the response defined in docs/CONTRATO_API_SALESFORCE.md.
const validated = $('Validate Sync Request').first().json;
const result = $input.first().json ?? {};

const upserted = Number(result.upserted ?? 0);

// db_rejected carries records the statement could not store, e.g. a vehicle
// whose account was never synced. Postgres returns it as a JSON array.
let dbRejected = result.db_rejected ?? [];
if (typeof dbRejected === 'string') {
  try { dbRejected = JSON.parse(dbRejected); } catch (e) { dbRejected = []; }
}
if (!Array.isArray(dbRejected)) {
  dbRejected = [];
}

const rejectedRecords = [...(validated.rejected_records ?? []), ...dbRejected];

const body = {
  syncBatchId: validated.sync_batch_id,
  received: validated.received,
  upserted: upserted,
  rejected: rejectedRecords.length,
  rejectedRecords: rejectedRecords,
};

if (validated.entity === 'reassign') {
  delete body.syncBatchId;
  // A PATCH against an account that does not exist changes nothing.
  if (upserted === 0) {
    return [{
      json: {
        statusCode: 404,
