  syncBatchId: validated.sync_batch_id,
  received: validated.received,
  upserted: upserted,
  rejected: rejectedRecords.length,
  rejectedRecords: rejectedRecords,
};

if (validated.entity === 'reassign') {
  delete body.syncBatchId;
  // A PATCH against an account that does not exist changes nothing.
  if (upserted === 0) {
    return [{
      json: {
        statusCode: 404,
        body: {
          code: 'INVALID_PAYLOAD',
          message: 'La cuenta no existe o esta purgada; no se reasigno nada.',
          details: [],
        },
      },
    }];
  }
  return [{ json: { statusCode: 200, body: { reassigned: upserted } } }];
}

return [{ json: { statusCode: 200, body: body } }];
